exercises.solution:
password = input()
has_upper = False
has_lower = False
has_digit = False
for ch in password:
    if ch.isupper():
        has_upper = True
    elif ch.islower():
        has_lower = True
    elif ch.isdigit():
        has_digit = True
if len(password) < 8:
    print("Weak: too short")
elif not has_upper:
    print("Weak: no uppercase letter")
elif not has_lower:
    print("Weak: no lowercase letter")
elif not has_digit:
    print("Weak: no digit")
else:
    print("Strong")

